const request = require('request');

const options = {
  method: 'GET',
  url: 'https://api.procore.com/rest/v1.1/projects/%7Bproject_id%7D/recycle_bin/incidents/witness_statements',
  qs: {
    incident_id: 'SOME_INTEGER_VALUE',
    page: 'SOME_INTEGER_VALUE',
    per_page: 'SOME_INTEGER_VALUE',
    'filters[created_at]': 'SOME_STRING_VALUE',
    'filters[date_received]': 'SOME_STRING_VALUE',
    'filters[witness_id]': 'SOME_ARRAY_VALUE',
    'filters[query]': 'SOME_STRING_VALUE',
    sort: 'SOME_STRING_VALUE'
  },
  headers: {Authorization: 'Bearer REPLACE_BEARER_TOKEN'}
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("https://api.procore.com/rest/v1.1/projects/%7Bproject_id%7D/recycle_bin/incidents/witness_statements?incident_id=SOME_INTEGER_VALUE&page=SOME_INTEGER_VALUE&per_page=SOME_INTEGER_VALUE&filters%5Bcreated_at%5D=SOME_STRING_VALUE&filters%5Bdate_received%5D=SOME_STRING_VALUE&filters%5Bwitness_id%5D=SOME_ARRAY_VALUE&filters%5Bquery%5D=SOME_STRING_VALUE&sort=SOME_STRING_VALUE"),
    Headers =
    {
        { "Authorization", "Bearer REPLACE_BEARER_TOKEN" },
    },
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

